  else upd_ctx (fun c => set_seq (c_seq c + 1) c) st.

Definition sc_in_seq_range (sc : Z) : bool := (7 <=? sc) && (sc <? 39).  (* [comment removed for export] *)

(* [comment removed for export] *)
