Definition slot_of (st : mstate) (g : aptr) (idx : Z) : aptr := slot_start' (get_meta_rec st g) idx.

(* [comment removed for export] *)
Definition enframe_read_off {R} (st : mstate) (g : aptr) (idx n ctr : Z) (k : Z -> M R) : M R :=
