Lemma am_after_brk_ctrl nu k1 k2 b1 b2 :
  KREL RR k1 k2 -> BREL RR b1 b2 ->
  forall o st cst, cst = strip st -> strel RR (prun o (am_after_brk st nu k1 b1)) (am_after_brk cst nu k2 b2).
