Lemma alloc_meta_ctrl k1 k2 b1 b2 :
  KREL RR k1 k2 -> BREL RR b1 b2 ->
  forall o st cst, cst = strip st -> strel RR (prun o (alloc_meta st k1 b1)) (alloc_meta cst k2 b2).
