Lemma try_avail_ctrl sc k1 k2 b1 b2 :
  KREL RR k1 k2 -> BREL RR b1 b2 ->
  forall o st cst, cst = strip st -> strel RR (prun o (try_avail sc st k1 b1)) (try_avail sc cst k2 b2).
Proof.
