Definition zrange (lo n : Z) : list Z := map (fun i => lo + Z.of_nat i) (seq 0 (Z.to_nat n)).
Lemma in_zrange lo n x : 0 <= n -> (In x (zrange lo n) <-> lo <= x < lo + n).
