Definition stc_f (k : Z) : bool := let sc := stc_k k in (0 <=? sc) && (sc <? 48) && (k + 1 <=? size_class sc).
Lemma stc_ok_b_true : forallb stc_f (zrange 0 8191) = true.
Proof.
